public sealed class ClockEntryService
{
    private readonly IClockEntryRepository _clockEntries;

    public ClockEntryService(IClockEntryRepository clockEntries)
    {
        _clockEntries = clockEntries;
    }

    public bool TryClockIn(int employeeId, DateTime clockIn)
    {
        if (_clockEntries.GetOpenClockEntry(employeeId) is not null)
        {
            return false;
        }

        _clockEntries.SaveClockEntry(new ClockEntry(employeeId, clockIn));
        return true;
    }

    public bool TryClockOut(int employeeId, DateTime clockOut)
    {
        ClockEntry? openEntry = _clockEntries.GetOpenClockEntry(employeeId);
        if (openEntry is null)
        {
            return false;
        }

        openEntry.ClockOutEntry(clockOut);
        return true;
    }
}
